package net.civeira.phylax.feature.observe.observedembed.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedembed.domain.ObservedEmbed;
import net.civeira.phylax.feature.observe.observedembed.domain.gateway.ObservedEmbedCursor;
import net.civeira.phylax.feature.observe.observedembed.domain.gateway.ObservedEmbedFilter;

class ObservedEmbedSlider extends Slider<ObservedEmbed> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedEmbedCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedEmbedFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedEmbedFilter, ObservedEmbedCursor, Iterator<ObservedEmbed>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedEmbedSlider(final Iterator<ObservedEmbed> multi, final int limit,
      final BiFunction<ObservedEmbedFilter, ObservedEmbedCursor, Iterator<ObservedEmbed>> gateway,
      final ObservedEmbedFilter filter, final ObservedEmbedCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedEmbeds
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedEmbed> next(List<ObservedEmbed> observedEmbeds, int limit) {
    ObservedEmbed last = observedEmbeds.get(observedEmbeds.size() - 1);
    ObservedEmbedCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
